import {spawn} from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

// Test-only instrumentation reports the address of this child's actual listener
// over its private IPC channel. No reserve/close/rebind race or fixed port exists.
const childEntry = `
const http=require('node:http');
const listen=http.Server.prototype.listen;
http.Server.prototype.listen=function(...args){
  this.once('listening',()=>{
    if(process.send)process.send({type:'attendance-runtime-listening',pid:process.pid,address:this.address()});
  });
  return listen.apply(this,args);
};
require(process.argv[1]);
`;
const delay=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function bounded(promise,ms,message){
  let timer;
  try{return await Promise.race([promise,new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error(message)),ms);})]);}
  finally{clearTimeout(timer);}
}

export function createAttendanceRuntime({runtime,database,startupBudgetMs=Number(process.env.WFM_PROOF_STARTUP_BUDGET_MS||30000)}){
  if(!Number.isFinite(startupBudgetMs)||startupBudgetMs<=0)throw Error('Invalid attendance startup deadline.');
  let current;
  async function stop(){
    const child=current;
    if(!child)return;
    if(!child.exited)child.process.kill('SIGTERM');
    try{await bounded(child.closed,2000,'Attendance runtime did not stop after SIGTERM.');}
    catch{
      if(!child.exited)child.process.kill('SIGKILL');
      await bounded(child.closed,2000,'Attendance runtime could not be reaped.');
    }
    if(current===child)current=undefined;
  }
  async function start(){
    if(current&&!current.exited)throw Error('An attendance test runtime is already active.');
    if(current)await stop();
    const loader=path.join(runtime,'local-paths.cjs');
    const args=[...(fs.existsSync(loader)?['--require',loader]:[]),'-e',childEntry,path.join(runtime,'security-runtime/bootstrap.cjs')];
    const child={process:spawn(process.execPath,args,{
      cwd:runtime,
      env:{...process.env,PORT:'0',WFM_DB:database,WFM_HOSTED_STAGING:'false',NODE_ENV:'test'},
      stdio:['ignore','pipe','pipe','ipc']
    }),exited:false,diagnostics:'',origin:'',failure:null,lastHealthStatus:null};
    current=child;
    child.closed=new Promise(resolve=>child.process.once('close',resolve));
    child.process.once('exit',()=>{child.exited=true;});
    child.process.once('error',error=>{child.failure=error;});
    for(const [name,stream] of [['stdout',child.process.stdout],['stderr',child.process.stderr]]){
      stream.on('data',data=>{child.diagnostics=(child.diagnostics+'['+name+'] '+data).slice(-16384);});
    }
    child.process.on('message',message=>{
      if(message?.type!=='attendance-runtime-listening')return;
      const address=message.address;
      if(message.pid!==child.process.pid||address?.address!=='127.0.0.1'||!Number.isInteger(address.port)||address.port<=0){
        child.failure=Error('Attendance runtime reported an invalid owned loopback listener.');return;
      }
      child.origin='http://127.0.0.1:'+address.port;
    });
    const deadline=Date.now()+startupBudgetMs;
    try{
      while(Date.now()<deadline){
        if(child.failure)throw child.failure;
        if(child.exited)throw Error('Attendance runtime exited before readiness.');
        if(child.origin){
          try{
            const response=await fetch(child.origin+'/api/health',{signal:AbortSignal.timeout(Math.max(1,Math.min(1000,deadline-Date.now())))});
            child.lastHealthStatus=response.status;
            const healthy=response.ok;
            await response.body?.cancel();
            if(healthy&&!child.exited&&!child.failure)return child.origin;
          }catch{}
        }
        const remaining=deadline-Date.now();
        if(remaining>0)await delay(Math.min(50,remaining));
      }
      throw Error('Attendance runtime did not become healthy within '+startupBudgetMs+'ms. phase='+(child.origin?'waiting-health':'waiting-listener')+'; lastHealthStatus='+(child.lastHealthStatus??'none'));
    }catch(error){
      await stop();
      throw Error(error.message+'\n'+child.diagnostics);
    }
  }
  return {start,stop,get origin(){return current?.origin||'';},get pid(){return current?.process.pid;}};
}

import test from 'node:test';
import assert from 'node:assert/strict';
import http from 'node:http';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {createAttendanceRuntime} from './attendance-runtime-harness.mjs';

function fixture(t,body) {
  const runtime=fs.mkdtempSync(path.join(os.tmpdir(),'attendance-harness-fixture-'));
  fs.mkdirSync(path.join(runtime,'security-runtime'));
  fs.writeFileSync(path.join(runtime,'security-runtime/bootstrap.cjs'),body);
  t.after(()=>fs.rmSync(runtime,{recursive:true,force:true}));
  return runtime;
}
const healthyRuntime="const http=require('node:http');const s=http.createServer((req,res)=>{res.setHeader('content-type','application/json');res.end(JSON.stringify({pid:process.pid,database:process.env.WFM_DB}));});s.listen(Number(process.env.PORT),'127.0.0.1');process.on('SIGTERM',()=>{s.close(()=>process.exit(0));s.closeAllConnections();});";

test('owns its listener even when the former fixed port serves a healthy foreign process',async t=>{
  const foreign=http.createServer((req,res)=>{res.setHeader('content-type','application/json');res.end(JSON.stringify({pid:'foreign-process'}));});
  await new Promise((resolve,reject)=>{
    foreign.once('error',error=>error.code==='EADDRINUSE'?resolve():reject(error));
    foreign.listen(43822,'127.0.0.1',resolve);
  });
  t.after(()=>foreign.listening?new Promise(resolve=>{foreign.close(resolve);foreign.closeAllConnections();}):undefined);
  const runtime=fixture(t,healthyRuntime);
  const database=path.join(runtime,'state.sqlite');
  const harness=createAttendanceRuntime({runtime,database,startupBudgetMs:2000});
  t.after(()=>harness.stop());
  await harness.start();
  const first=await (await fetch(harness.origin+'/api/health')).json();
  assert.equal(first.pid,harness.pid,'Readiness and requests must reach the child started by this test.');
  assert.equal(first.database,database);
  assert.notEqual(new URL(harness.origin).port,'43822');
  await harness.stop();
  await harness.start();
  const second=await (await fetch(harness.origin+'/api/health')).json();
  assert.equal(second.pid,harness.pid);
  assert.notEqual(second.pid,first.pid);
  assert.equal(second.database,database,'Restart must preserve the same test database path.');
});

test('bounds a stalled health request and preserves startup diagnostics',async t=>{
  const runtime=fixture(t,"const http=require('node:http');console.error('fixture-health-stalled');const s=http.createServer(()=>{});s.listen(Number(process.env.PORT),'127.0.0.1');process.on('SIGTERM',()=>{s.close(()=>process.exit(0));s.closeAllConnections();});");
  const harness=createAttendanceRuntime({runtime,database:path.join(runtime,'state.sqlite'),startupBudgetMs:250});
  t.after(()=>harness.stop());
  const started=Date.now();
  await assert.rejects(harness.start(),/fixture-health-stalled/);
  assert.ok(Date.now()-started<2000,'Startup must obey its deadline even when HTTP never returns.');
});

test('cleans up a child that exits by signal without waiting for a second exit event',async t=>{
  const runtime=fixture(t,healthyRuntime);
  const harness=createAttendanceRuntime({runtime,database:path.join(runtime,'state.sqlite'),startupBudgetMs:2000});
  t.after(()=>harness.stop());
  await harness.start();
  process.kill(harness.pid,'SIGKILL');
  await new Promise(resolve=>setTimeout(resolve,30));
  const started=Date.now();
  await harness.stop();
  assert.ok(Date.now()-started<1000,'A signal-exited child must already count as stopped.');
});

test('startup timeout distinguishes a child that never opens its owned listener',async t=>{
  const runtime=fixture(t,"setInterval(()=>{},1000);");
  const harness=createAttendanceRuntime({runtime,database:path.join(runtime,'state.sqlite'),startupBudgetMs:500});
  t.after(()=>harness.stop());
  await assert.rejects(harness.start(),/phase=waiting-listener; lastHealthStatus=none/);
});

test('startup timeout reports persistent unhealthy responses without accepting the listener as readiness',async t=>{
  const runtime=fixture(t,"const http=require('node:http');const s=http.createServer((req,res)=>{res.statusCode=503;res.end('not ready');});s.listen(Number(process.env.PORT),'127.0.0.1');process.on('SIGTERM',()=>{s.close(()=>process.exit(0));s.closeAllConnections();});");
  const harness=createAttendanceRuntime({runtime,database:path.join(runtime,'state.sqlite'),startupBudgetMs:1000});
  t.after(()=>harness.stop());
  await assert.rejects(harness.start(),/phase=waiting-health; lastHealthStatus=503/);
});
